const GENERIC_NOTE = "Default volumetric speed and retraction are generic; please tune for your printer.";

// Helper to create full profile with defaults for new fields
// Materials that warp and need cooling held back, vs. elastomers that need a slow flow rate.
// Used only for defaults — an explicit value in the preset always wins.
const WARP_PRONE: FilamentType[] = ['ABS', 'ASA', 'PC', 'Nylon', 'PA-CF', 'PA-GF', 'PA6', 'PA12', 'PEI', 'PP', 'HIPS'];
const FLEXIBLE: FilamentType[] = ['TPU', 'TPE', 'PEBA'];

const createPreset = (base: Partial<FilamentProfile> & { id: string, profileName: string, printerBrand: PrinterBrand, manufacturer: string, filamentType: FilamentType, nozzleTemp: number, bedTemp: number }): FilamentProfile => {
    return {
        filamentDiameter: 1.75,
        printerModel: 'Generic',
        nozzleDiameter: 0.4,
        printSpeed: 60,
        retractionDistance: 0.8,
        retractionSpeed: 35,
        spoolWeight: 1000,
        filamentCost: 25,
        notes: GENERIC_NOTE,
        // Defaults for new fields if not provided
        nozzleTempInitial: base.nozzleTemp + 5,
        bedTempInitial: base.bedTemp,
        maxVolumetricSpeed: FLEXIBLE.includes(base.filamentType) ? 3 : (base.filamentType === 'PLA' ? 15 : 10),
        fanSpeedMin: WARP_PRONE.includes(base.filamentType) ? 0 : 100,
        fanSpeedMax: WARP_PRONE.includes(base.filamentType) ? 20 : 100,
        ...base
    } as FilamentProfile;
};

